/* ---------------------------------------------------------
   HELPERS
--------------------------------------------------------- */

function normalize(str) {
  return str
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z\s]/g, "")
    .trim();
}

function findPlayer(list, guess) {
  const g = normalize(guess);
  if (!g) return null;
  return (
    list.find((p) => normalize(p.name) === g) ||
    list.find((p) => {
      const parts = normalize(p.name).split(" ");
      const last = parts[parts.length - 1];
      return g === last || g.endsWith(last);
    }) ||
    null
  );
}

function teamByAbbr(abbr, teams) {
  return teams.find((t) => t.abbr === abbr);
}

function teamNames(abbrs, teams) {
  return abbrs.map((a) => (teamByAbbr(a, teams) ? teamByAbbr(a, teams).name : a)).join(", ");
}

function emptySlots(count) {
  return Array.from({ length: count }, () => ({
    team: null,
    name: "",
    manualStat: "",
    result: null,
  }));
}

function randomTeam(teams) {
  return teams[Math.floor(Math.random() * teams.length)];
}

// Custom per-lineup-size overrides (e.g. cat.targets20) take priority;
// otherwise the 10-spot target scales proportionally to lineup size.
function getTarget(cat, difficulty, slotCount) {
  const sizedOverrides = cat[`targets${slotCount}`];
  if (sizedOverrides && sizedOverrides[difficulty] != null) {
    return sizedOverrides[difficulty];
  }
  return Math.round(cat.targets[difficulty] * (slotCount / 10));
}

function todayLocalStr() {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}

function yesterdayLocalStr() {
  const d = new Date();
  d.setDate(d.getDate() - 1);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}

// Every possible daily-question "slot": one entry per (sport, category,
// team-or-all-time) combination. Built once from real data — no hand
// curation, no hardcoded counts, so it stays correct if categories or
// teams are ever added later.
function buildAllDailyCombos() {
  const combos = [];
  for (const sportKey of SPORT_KEYS) {
    const categoryKeys = Object.keys(SPORTS[sportKey].categories);
    const teamsList = SPORTS[sportKey].teams;
    for (const categoryKey of categoryKeys) {
      combos.push({ sport: sportKey, category: categoryKey, teamAbbr: null }); // all-time
      for (const t of teamsList) {
        combos.push({ sport: sportKey, category: categoryKey, teamAbbr: t.abbr });
      }
    }
  }
  return combos;
}

function pickDistractors(pool, count) {
  const candidates = pool.slice(1, 11);
  const picked = [];
  while (picked.length < count && candidates.length > 0) {
    const idx = Math.floor(Math.random() * candidates.length);
    picked.push(candidates[idx]);
    candidates.splice(idx, 1);
  }
  return picked;
}

function shuffleRandom(arr) {
  const result = [...arr];
  for (let i = result.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [result[i], result[j]] = [result[j], result[i]];
  }
  return result;
}

// Turns one combo (sport/category/team-or-null) into an actual question:
// text, correct answer, and 4 shuffled multiple-choice options.
function buildQuestionFromCombo(combo) {
  const cat = SPORTS[combo.sport].categories[combo.category];
  const label = combo.category.replace(/^Career /, "").toLowerCase();

  let team = null;
  let pool = cat.players;
  if (combo.teamAbbr) {
    const candidateTeam = SPORTS[combo.sport].teams.find((t) => t.abbr === combo.teamAbbr);
    const filtered = cat.players.filter((p) => p.teams.includes(combo.teamAbbr));
    if (candidateTeam && filtered.length > 0) {
      team = candidateTeam;
      pool = filtered; // already sorted descending, since cat.players is
    }
  }

  const answer = pool[0];
  const questionText = team
    ? `Which player has the most career ${label} among those who played for the ${team.name}?`
    : `Who has the most career ${label} of all time?`;

  const distractors = pickDistractors(pool, 3);
  const options = shuffleRandom([answer, ...distractors].map((p) => p.name));

  return {
    sport: combo.sport,
    category: combo.category,
    team,
    questionText,
    answerName: answer.name,
    answerValue: answer.value,
    unit: cat.unit,
    options,
  };
}

// Picks today's combo from a shuffled "bag" of every possible combo,
// guaranteeing no repeat until the whole set has been seen once. State
// (the shuffled order, position, and today's already-picked combo) is
// persisted locally so re-opening the app the same day shows the same
// question, and the sequence survives between sessions.
function pickTodaysCombo(daily) {
  const today = todayLocalStr();
  if (daily.bagDate === today && daily.currentCombo) {
    return { combo: daily.currentCombo, bag: daily };
  }

  let order = daily.bagOrder || [];
  let position = daily.bagPosition || 0;

  if (order.length === 0 || position >= order.length) {
    const allCombos = buildAllDailyCombos();
    order = shuffleRandom(allCombos.map((_, i) => i));
    position = 0;
  }

  const allCombos = buildAllDailyCombos();
  const combo = allCombos[order[position]];
  const newBag = {
    ...daily,
    bagOrder: order,
    bagPosition: position + 1,
    bagDate: today,
    currentCombo: combo,
  };
  return { combo, bag: newBag };
}


function formatMs(ms) {
  const totalTenths = Math.floor(ms / 100);
  const minutes = Math.floor(totalTenths / 600);
  const seconds = Math.floor((totalTenths % 600) / 10);
  const tenths = totalTenths % 10;
  return `${minutes}:${String(seconds).padStart(2, "0")}.${tenths}`;
}

// All three sounds are synthesized entirely in-browser with the Web
// Audio API — no audio files to host, license, or bundle. They share one
// AudioContext (created lazily on first use) rather than each spinning up
// its own, since the tick sound alone can fire dozens of times per
// session. Every call is wrapped in try/catch since some browsers
// restrict audio until the user has interacted with the page, and a
// missing sound should never break the actual game.
let sharedAudioCtx = null;
let isMuted = false;
function getAudioCtx() {
  if (!sharedAudioCtx) {
    sharedAudioCtx = new (window.AudioContext || window.webkitAudioContext)();
  }
  return sharedAudioCtx;
}

function playTickSound() {
  if (isMuted) return;
  try {
    const ctx = getAudioCtx();
    const now = ctx.currentTime;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = "square";
    osc.frequency.value = 900;
    gain.gain.setValueAtTime(0.15, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.03);
    osc.connect(gain).connect(ctx.destination);
    osc.start(now);
    osc.stop(now + 0.03);
  } catch (err) {
    // Audio unavailable — fail silently, never block gameplay.
  }
}

function playSuccessSound() {
  if (isMuted) return;
  try {
    const ctx = getAudioCtx();
    const now = ctx.currentTime;

    // Bright ascending arpeggio — the "you did it" cue.
    const notes = [523.25, 659.25, 783.99, 1046.5]; // C5 E5 G5 C6
    notes.forEach((freq, i) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = "triangle";
      osc.frequency.value = freq;
      const start = now + i * 0.09;
      gain.gain.setValueAtTime(0, start);
      gain.gain.linearRampToValueAtTime(0.25, start + 0.02);
      gain.gain.exponentialRampToValueAtTime(0.001, start + 0.3);
      osc.connect(gain).connect(ctx.destination);
      osc.start(start);
      osc.stop(start + 0.35);
    });

    // A short filtered-noise swell layered underneath for a "crowd" texture.
    const bufferSize = ctx.sampleRate * 0.6;
    const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) {
      data[i] = (Math.random() * 2 - 1) * 0.3;
    }
    const noise = ctx.createBufferSource();
    noise.buffer = buffer;
    const noiseFilter = ctx.createBiquadFilter();
    noiseFilter.type = "bandpass";
    noiseFilter.frequency.value = 2000;
    const noiseGain = ctx.createGain();
    noiseGain.gain.setValueAtTime(0, now);
    noiseGain.gain.linearRampToValueAtTime(0.15, now + 0.05);
    noiseGain.gain.exponentialRampToValueAtTime(0.001, now + 0.6);
    noise.connect(noiseFilter).connect(noiseGain).connect(ctx.destination);
    noise.start(now);
    noise.stop(now + 0.6);
  } catch (err) {
    // Audio unavailable — fail silently, never block gameplay.
  }
}

function playMissSound() {
  if (isMuted) return;
  try {
    const ctx = getAudioCtx();
    const now = ctx.currentTime;

    // Classic descending "wah wah womp" — the disappointment cue.
    const notes = [392, 349.23, 293.66]; // G4, F4, D4
    notes.forEach((freq, i) => {
      const start = now + i * 0.28;
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = "sawtooth";
      osc.frequency.setValueAtTime(freq, start);
      osc.frequency.linearRampToValueAtTime(freq * 0.85, start + 0.25);
      gain.gain.setValueAtTime(0, start);
      gain.gain.linearRampToValueAtTime(0.2, start + 0.03);
      gain.gain.exponentialRampToValueAtTime(0.001, start + 0.28);
      osc.connect(gain).connect(ctx.destination);
      osc.start(start);
      osc.stop(start + 0.3);
    });
  } catch (err) {
    // Audio unavailable — fail silently, never block gameplay.
  }
}

function challengeSummaryText(cat, difficulty, total, speedRun, runEndTime, runStartTime) {
  const diffLabel = difficulty.charAt(0).toUpperCase() + difficulty.slice(1);
  if (speedRun && runStartTime && runEndTime) {
    return `finished a ${diffLabel} ${cat.unit} run in ${formatMs(runEndTime - runStartTime)}`;
  }
  return `hit ${total.toLocaleString()} ${cat.unit} on ${diffLabel}`;
}

/* ---------------------------------------------------------
   COMPONENT
--------------------------------------------------------- */

export default function StatBlitz() {
  const [sport, setSport] = useState("baseball");
  const [category, setCategory] = useState(Object.keys(SPORTS.baseball.categories)[0]);
  const [difficulty, setDifficulty] = useState("medium");
  const [slotCount, setSlotCount] = useState(10);
  const [slots, setSlots] = useState(() => emptySlots(10));
  const [activeIndex, setActiveIndex] = useState(0);
  const slotRefs = useRef([]);
  const summaryRef = useRef(null);
  const [spinning, setSpinning] = useState(false);
  const [displayTeam, setDisplayTeam] = useState(SPORTS.baseball.teams[0]);
  const [revealed, setRevealed] = useState(false);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [hardMode, setHardMode] = useState(false);
  const [speedRun, setSpeedRun] = useState(false);
  const [runStartTime, setRunStartTime] = useState(null);
  const [runEndTime, setRunEndTime] = useState(null);
  const [bestTime, setBestTime] = useState(null);
  const [, forceTick] = useState(0);

  const [challengeTarget, setChallengeTarget] = useState(null); // { code, sport, category, difficulty, hardMode, speedRun, slotCount, total, unit, timeMs }
  const [myChallengeCode, setMyChallengeCode] = useState(null);
  const [challengeInput, setChallengeInput] = useState("");
  const [challengePanel, setChallengePanel] = useState(null); // null | "create" | "enter"
  const [challengeStatus, setChallengeStatus] = useState("");
  const [challengeBusy, setChallengeBusy] = useState(false);

  const [muted, setMuted] = useState(false);

  // Load the saved mute preference from this device once, on first render.
  useEffect(() => {
    try {
      const saved = localStorage.getItem("statBlitzMuted");
      if (saved !== null) setMuted(saved === "true");
    } catch (err) {
      // localStorage unavailable — preference just won't persist this session
    }
  }, []);

  // Keep the module-level mute flag (checked by the standalone sound
  // functions, which live outside the component) in sync with this state.
  useEffect(() => {
    isMuted = muted;
    try {
      localStorage.setItem("statBlitzMuted", String(muted));
    } catch (err) {
      // localStorage unavailable — preference just won't persist this session
    }
  }, [muted]);

  const [dailyMode, setDailyMode] = useState(false); // is the daily question panel open
  const [dailyQuestion, setDailyQuestion] = useState(null); // built question text/options for display
  const [daily, setDaily] = useState({
    streak: 0,
    lastAnsweredDate: null, // last day they submitted any guess
    lastCorrectDate: null, // last day they got it right
    lastGuess: "",
    lastCorrect: null,
    bagOrder: [], // shuffled combo indices — the "bag" of unseen questions
    bagPosition: 0,
    bagDate: null, // date the current bag position was last picked for
    currentCombo: null, // today's already-picked combo, so reopening shows the same question
  });

  // Load the saved daily-question state from this device once, on first render.
  useEffect(() => {
    try {
      const saved = localStorage.getItem("statBlitzDaily");
      if (saved) {
        setDaily((prev) => ({ ...prev, ...JSON.parse(saved) }));
      }
    } catch (err) {
      // localStorage unavailable — daily progress just won't persist this session
    }
  }, []);

  const teams = SPORTS[sport].teams;
  const CATEGORY_KEYS = Object.keys(SPORTS[sport].categories);
  const cat = SPORTS[sport].categories[category];
  const target = getTarget(cat, difficulty, slotCount);

  const activeSlot = activeIndex < slotCount ? slots[activeIndex] : null;
  const roundComplete = activeIndex >= slotCount;

  function isScored(status) {
    return status === "found" || status === "confirmed";
  }

  function isResolved(status) {
    return status === "found" || status === "confirmed" || status === "missed";
  }

  const canSpin =
    !spinning &&
    !roundComplete &&
    !(activeSlot && activeSlot.result && isResolved(activeSlot.result.status));

  // Auto-advance to the next slot a beat after a slot resolves (found,
  // self-reported, or missed).
  useEffect(() => {
    if (activeSlot && activeSlot.result && isResolved(activeSlot.result.status)) {
      const timer = setTimeout(() => {
        setActiveIndex((idx) => Math.min(idx + 1, slotCount));
      }, 800);
      return () => clearTimeout(timer);
    }
  }, [slots, activeIndex, slotCount]);

  // Only slot #1 needs a manual tap. From slot #2 onward, once the
  // board advances into a fresh slot, spin it automatically.
  useEffect(() => {
    if (activeIndex > 0 && activeIndex < slotCount) {
      const slot = slots[activeIndex];
      if (slot && !slot.team) {
        spin();
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeIndex]);

  // Speed run: tick the display every 100ms while a run is live.
  useEffect(() => {
    if (!speedRun || !runStartTime || runEndTime) return;
    const interval = setInterval(() => forceTick((t) => t + 1), 100);
    return () => clearInterval(interval);
  }, [speedRun, runStartTime, runEndTime]);

  // Speed run: stop the clock the moment all 10 slots are filled.
  useEffect(() => {
    if (speedRun && roundComplete && runStartTime && !runEndTime) {
      const end = Date.now();
      setRunEndTime(end);
      const elapsed = end - runStartTime;
      setBestTime((prev) => (prev === null || elapsed < prev ? elapsed : prev));
    }
  }, [roundComplete, speedRun, runStartTime, runEndTime]);

  // Auto-scroll to the newly active slot as the lineup advances, so you
  // never have to manually scroll down to find what's next.
  useEffect(() => {
    if (roundComplete) return;
    const el = slotRefs.current[activeIndex];
    if (el) {
      el.scrollIntoView({ behavior: "smooth", block: "center" });
    }
  }, [activeIndex, roundComplete]);

  // Once the lineup is complete, scroll back up to the running total so
  // the final score is immediately visible.
  useEffect(() => {
    if (roundComplete && summaryRef.current) {
      summaryRef.current.scrollIntoView({ behavior: "smooth", block: "start" });
    }
  }, [roundComplete]);

  // Play a reaction sound the moment the lineup finishes — a cheer if
  // the target was hit, a letdown sound if it fell short.
  useEffect(() => {
    if (!roundComplete) return;
    if (goalReached) {
      playSuccessSound();
    } else {
      playMissSound();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [roundComplete]);

  function toggleSpeedRun() {
    setSpeedRun((s) => !s);
    setRunStartTime(null);
    setRunEndTime(null);
  }

  function generateChallengeCode() {
    const chars = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"; // no O/0/I/1 confusion
    let code = "";
    for (let i = 0; i < 5; i++) code += chars[Math.floor(Math.random() * chars.length)];
    return code;
  }

  async function createChallenge() {
    setChallengeBusy(true);
    setChallengeStatus("");
    const code = generateChallengeCode();
    const payload = {
      sport,
      category,
      difficulty,
      hardMode,
      speedRun,
      slotCount,
      total: runningTotal,
      unit: cat.unit,
      timeMs: speedRun && runStartTime && runEndTime ? runEndTime - runStartTime : null,
    };
    try {
      await window.storage.set(`challenge:${code}`, JSON.stringify(payload), true);
      setMyChallengeCode(code);
      setChallengeStatus("");
    } catch (err) {
      setChallengeStatus("Couldn't create the challenge — try again.");
    }
    setChallengeBusy(false);
  }

  async function copyChallengeMessage() {
    if (!myChallengeCode) return;
    const scoreText = challengeSummaryText(cat, difficulty, runningTotal, speedRun, runEndTime, runStartTime);
    const message = `I ${scoreText} in a ${slotCount}-slot ${SPORTS[sport].label} challenge on Stat Blitz. Beat me — enter code ${myChallengeCode} in the app!`;
    try {
      await navigator.clipboard.writeText(message);
      setChallengeStatus("Copied! Paste it to your friend.");
    } catch (err) {
      setChallengeStatus(`Code: ${myChallengeCode} (copy failed — just share the code)`);
    }
  }

  async function loadChallenge() {
    const code = challengeInput.trim().toUpperCase();
    if (!code) return;
    setChallengeBusy(true);
    setChallengeStatus("");
    try {
      const result = await window.storage.get(`challenge:${code}`, true);
      const data = JSON.parse(result.value);
      const n = data.slotCount || 10;
      const loadedSport = data.sport && SPORTS[data.sport] ? data.sport : "baseball";
      setChallengeTarget({ ...data, code });
      setChallengePanel(null);
      setChallengeInput("");
      setSport(loadedSport);
      setCategory(data.category);
      setDifficulty(data.difficulty);
      setHardMode(!!data.hardMode);
      setSpeedRun(!!data.speedRun);
      setSlotCount(n);
      setSlots(emptySlots(n));
      setActiveIndex(0);
      setRevealed(false);
      setRunStartTime(null);
      setRunEndTime(null);
      setBestTime(null);
    } catch (err) {
      setChallengeStatus("Couldn't find that code — double-check it.");
    }
    setChallengeBusy(false);
  }

  function clearChallenge() {
    setChallengeTarget(null);
    setMyChallengeCode(null);
    setChallengeStatus("");
    setChallengePanel(null);
  }

  function startDaily() {
    const { combo, bag } = pickTodaysCombo(daily);
    setDaily(bag);
    setDailyQuestion(buildQuestionFromCombo(combo));
    setDailyMode(true);
    try {
      localStorage.setItem("statBlitzDaily", JSON.stringify(bag));
    } catch (err) {
      // localStorage unavailable — daily progress just won't persist this session
    }
  }

  function exitDaily() {
    setDailyMode(false);
  }

  function submitDailyGuess(guessName) {
    if (!dailyQuestion) return;
    const today = todayLocalStr();
    if (daily.lastAnsweredDate === today) return; // already answered today

    const isCorrect = guessName === dailyQuestion.answerName;
    const wasYesterday = daily.lastCorrectDate === yesterdayLocalStr();
    const newStreak = isCorrect ? (wasYesterday ? daily.streak + 1 : 1) : 0;

    const updated = {
      ...daily,
      streak: newStreak,
      lastAnsweredDate: today,
      lastCorrectDate: isCorrect ? today : daily.lastCorrectDate,
      lastGuess: guessName,
      lastCorrect: isCorrect,
    };
    setDaily(updated);

    try {
      localStorage.setItem("statBlitzDaily", JSON.stringify(updated));
    } catch (err) {
      // localStorage unavailable — streak just won't persist this session
    }
  }

  function changeSport(key) {
    setSport(key);
    const firstCategory = Object.keys(SPORTS[key].categories)[0];
    setCategory(firstCategory);
    setSlots(emptySlots(slotCount));
    setActiveIndex(0);
    setRevealed(false);
    setRunStartTime(null);
    setRunEndTime(null);
    setBestTime(null);
    setChallengeTarget(null);
    setMyChallengeCode(null);
    setChallengeStatus("");
    setChallengePanel(null);
  }

  function changeCategory(key) {
    setCategory(key);
    setSlots(emptySlots(slotCount));
    setActiveIndex(0);
    setRevealed(false);
    setRunStartTime(null);
    setRunEndTime(null);
    setBestTime(null);
  }

  function changeDifficulty(d) {
    setDifficulty(d);
    setRunStartTime(null);
    setRunEndTime(null);
    setBestTime(null);
  }

  function changeSlotCount(n) {
    setSlotCount(n);
    setSlots(emptySlots(n));
    setActiveIndex(0);
    setRunStartTime(null);
    setRunEndTime(null);
    setBestTime(null);
  }

  function spin() {
    if (!canSpin) return;
    if (speedRun && !runStartTime) {
      setRunStartTime(Date.now());
    }
    setSpinning(true);
    let ticks = 0;
    const totalTicks = 9 + Math.floor(Math.random() * 4);
    const finalTeam = randomTeam(teams);
    const targetIndex = activeIndex;

    function tick() {
      ticks += 1;
      setDisplayTeam(randomTeam(teams));
      playTickSound();
      if (ticks >= totalTicks) {
        setDisplayTeam(finalTeam);
        assignTeamToSlot(targetIndex, finalTeam);
        setSpinning(false);
        return;
      }
      const delay = 20 + (ticks / totalTicks) * 70;
      setTimeout(tick, delay);
    }
    setTimeout(tick, 20);
  }

  function assignTeamToSlot(i, team) {
    setSlots((prev) => {
      const next = [...prev];
      next[i] = { team: team.abbr, name: "", manualStat: "", result: null };
      return next;
    });
  }

  function updateSlot(i, value) {
    setSlots((prev) => {
      const next = [...prev];
      next[i] = { ...next[i], name: value, manualStat: "", result: null };
      return next;
    });
  }

  // Only an explicit tap on a dropdown suggestion resolves a pool match —
  // typing alone (even an exact or last-name match) never auto-locks in.
  function selectPlayer(i, player) {
    setShowSuggestions(false);
    setSlots((prev) => {
      const slot = prev[i];
      if (!slot.team) return prev;

      let result;
      if (!player.teams.includes(slot.team)) {
        result = { status: "wrongteam", actual: player.value, actualTeams: player.teams };
      } else {
        const dupIndex = prev.findIndex(
          (s, idx) =>
            idx !== i &&
            s.result &&
            isScored(s.result.status) &&
            normalize(s.name) === normalize(player.name)
        );
        result =
          dupIndex !== -1
            ? { status: "duplicate" }
            : { status: "found", actual: player.value };
      }

      const next = [...prev];
      next[i] = { ...slot, name: player.name, result };
      return next;
    });
  }

  // If the player types a name but never taps a suggestion, treat it as
  // unverified once they leave the field — self-report is still available.
  function markUnverifiedIfNeeded(i) {
    setSlots((prev) => {
      const slot = prev[i];
      if (!slot.team || !slot.name.trim() || slot.result) return prev;
      const next = [...prev];
      next[i] = { ...slot, result: { status: "unverified" } };
      return next;
    });
  }

  function updateManualStat(i, value) {
    setSlots((prev) => {
      const next = [...prev];
      next[i] = { ...next[i], manualStat: value };
      return next;
    });
  }

  function confirmManual(i) {
    setSlots((prev) => {
      const slot = prev[i];
      if (!slot.name.trim()) return prev;
      const num = parseFloat(slot.manualStat);
      if (Number.isNaN(num) || num <= 0) return prev;

      const dupIndex = prev.findIndex(
        (s, idx) =>
          idx !== i &&
          s.result &&
          isScored(s.result.status) &&
          normalize(s.name) === normalize(slot.name)
      );
      if (dupIndex !== -1) {
        const next = [...prev];
        next[i] = { ...slot, result: { status: "duplicate" } };
        return next;
      }

      const next = [...prev];
      next[i] = { ...slot, result: { status: "confirmed", actual: num } };
      return next;
    });
  }

  function missSlot(i) {
    setSlots((prev) => {
      const slot = prev[i];
      if (!slot.team) return prev;
      const next = [...prev];
      next[i] = { ...slot, result: { status: "missed", actual: 0 } };
      return next;
    });
  }

  function resetBoard() {
    setSlots(emptySlots(slotCount));
    setActiveIndex(0);
    setRevealed(false);
    setRunStartTime(null);
    setRunEndTime(null);
  }

  const runningTotal = slots.reduce((sum, s) => {
    if (s.result && isScored(s.result.status)) {
      return sum + s.result.actual;
    }
    return sum;
  }, 0);

  const lockedCount = slots.filter((s) => s.result && isResolved(s.result.status)).length;

  const progressPct = Math.min(100, Math.round((runningTotal / target) * 100));
  const goalReached = runningTotal >= target;

  const playersByTeam = {};
  cat.players.forEach((p) => {
    p.teams.forEach((abbr) => {
      if (!playersByTeam[abbr]) playersByTeam[abbr] = [];
      playersByTeam[abbr].push(p);
    });
  });

  return (
    <div
      className="min-h-dvh w-full flex justify-center py-8 px-3"
      style={{ background: "radial-gradient(circle at 50% 0%, #16233d 0%, #0a1120 55%, #060a14 100%)" }}
    >
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Teko:wght@500;600;700&family=Inter:wght@400;500;600;700&display=swap');
        .font-scoreboard { font-family: 'Teko', sans-serif; letter-spacing: 0.02em; }
        .font-body { font-family: 'Inter', sans-serif; }
        @keyframes pulseglow {
          0%, 100% { box-shadow: 0 0 0 0 rgba(255,182,39,0.35); }
          50% { box-shadow: 0 0 0 10px rgba(255,182,39,0); }
        }
        .glow-ring { animation: pulseglow 2s ease-out infinite; }
        @media (prefers-reduced-motion: reduce) {
          .glow-ring { animation: none; }
        }
      `}</style>

      <div
        className="font-body w-full max-w-md rounded-[2rem] overflow-hidden border border-white/10"
        style={{ background: "linear-gradient(180deg, #101a2e 0%, #0b1424 100%)", boxShadow: "0 30px 60px -20px rgba(0,0,0,0.6)" }}
      >
        {/* HEADER */}
        <div className="relative px-6 pt-6 pb-4 text-center border-b border-white/10">
          <button
            onClick={() => setMuted((m) => !m)}
            title={muted ? "Unmute sounds" : "Mute sounds"}
            className="absolute top-4 right-4 w-8 h-8 rounded-full flex items-center justify-center text-sm bg-white/5 border border-white/10 text-slate-300 hover:bg-white/10"
          >
            {muted ? "🔇" : "🔊"}
          </button>
          <p className="text-[11px] tracking-widest text-amber-400/80 font-semibold mb-1">SPIN A TEAM. FIND ANY PLAYER WHO SUITED UP.</p>
          <h1 className="font-scoreboard text-white text-5xl leading-none">STAT BLITZ</h1>
          <p className="text-slate-400 text-sm mt-2">Build a lineup that hits the target total.</p>
        </div>

        {/* ACTIVE CHALLENGE BANNER */}
        {challengeTarget && (
          <div className="mx-5 mt-4 rounded-lg border border-amber-400/40 bg-amber-400/10 px-3 py-2 flex items-center justify-between gap-2">
            <p className="text-xs text-amber-300">
              🎯 Challenge <span className="font-semibold">{challengeTarget.code}</span>: beat{" "}
              {challengeTarget.speedRun && challengeTarget.timeMs
                ? `their time of ${formatMs(challengeTarget.timeMs)}`
                : `${challengeTarget.total.toLocaleString()} ${challengeTarget.unit}`}
            </p>
            <button onClick={clearChallenge} className="shrink-0 text-xs text-slate-400 hover:text-white">
              Clear
            </button>
          </div>
        )}

        {/* DAILY QUESTION */}
        {dailyMode && dailyQuestion ? (
          (() => {
            const answeredToday = daily.lastAnsweredDate === todayLocalStr();
            return (
              <div className="mx-5 mt-4 rounded-lg border border-orange-400/40 bg-orange-400/10 px-3 py-3">
                <div className="flex items-center justify-between gap-2">
                  <p className="text-[10px] font-semibold text-orange-300 uppercase tracking-wide">
                    🔥 Daily Question — {SPORTS[dailyQuestion.sport].label}
                  </p>
                  <button onClick={exitDaily} className="shrink-0 text-xs text-slate-400 hover:text-white">
                    Close
                  </button>
                </div>
                <p className="mt-1.5 text-sm text-white">{dailyQuestion.questionText}</p>

                {answeredToday ? (
                  <div className="mt-2">
                    <p className={"text-sm font-semibold " + (daily.lastCorrect ? "text-emerald-400" : "text-rose-400")}>
                      {daily.lastCorrect ? "✅ Correct!" : `❌ Not quite — you picked ${daily.lastGuess}`}
                    </p>
                    <p className="text-xs text-slate-400 mt-0.5">
                      Answer: {dailyQuestion.answerName} ({dailyQuestion.answerValue.toLocaleString()} {dailyQuestion.unit})
                    </p>
                    <p className="text-xs text-orange-300 mt-1">🔥 {daily.streak}-day streak — come back tomorrow!</p>
                  </div>
                ) : (
                  <div className="mt-2 grid grid-cols-1 gap-2">
                    {dailyQuestion.options.map((opt) => (
                      <button
                        key={opt}
                        onClick={() => submitDailyGuess(opt)}
                        className="px-3 py-2 rounded-lg text-sm text-left text-white bg-white/5 border border-white/10 hover:bg-orange-400/20 hover:border-orange-400/50 transition-colors"
                      >
                        {opt}
                      </button>
                    ))}
                  </div>
                )}
              </div>
            );
          })()
        ) : (
          <div className="mx-5 mt-4 rounded-lg border border-white/10 bg-white/5 px-3 py-2.5 flex items-center justify-between gap-2">
            <div>
              <p className="text-xs font-semibold text-slate-200">🔥 Daily Question</p>
              <p className="text-[10px] text-slate-500">
                {daily.streak > 0 ? `${daily.streak}-day streak` : "A new question every day"}
                {daily.lastAnsweredDate === todayLocalStr() ? " — answered today ✅" : ""}
              </p>
            </div>
            <button
              onClick={startDaily}
              className="shrink-0 px-3 py-1.5 rounded-full text-xs font-semibold bg-orange-400 text-slate-900 hover:bg-orange-300"
            >
              Play
            </button>
          </div>
        )}

        {/* SPORT PICKER */}
        <div className="px-5 pt-5">
          <label className="text-xs font-semibold text-slate-400 uppercase tracking-wide">Pick a sport</label>
          <div className="mt-2 flex gap-1.5">
            {SPORT_KEYS.map((key) => (
              <button
                key={key}
                onClick={() => changeSport(key)}
                className={
                  "flex-1 px-3 py-2 rounded-lg text-xs font-semibold border transition-colors " +
                  (sport === key
                    ? "bg-emerald-400 text-slate-900 border-emerald-400"
                    : "bg-white/5 text-slate-300 border-white/10 hover:bg-white/10")
                }
              >
                {SPORTS[key].label}
              </button>
            ))}
          </div>
        </div>

        {/* CATEGORY PICKER */}
        <div className="px-5 pt-5">
          <label className="text-xs font-semibold text-slate-400 uppercase tracking-wide">Pick a category</label>
          <div className="mt-2 flex flex-wrap gap-1.5">
            {CATEGORY_KEYS.map((key) => (
              <button
                key={key}
                onClick={() => changeCategory(key)}
                className={
                  "px-3 py-1.5 rounded-full text-xs font-medium border transition-colors " +
                  (category === key
                    ? "bg-amber-400 text-slate-900 border-amber-400"
                    : "bg-white/5 text-slate-300 border-white/10 hover:bg-white/10")
                }
              >
                {key}
              </button>
            ))}
          </div>
        </div>

        {/* DIFFICULTY / TARGET */}
        <div className="px-5 mt-4">
          <label className="text-xs font-semibold text-slate-400 uppercase tracking-wide">Target — combined {cat.unit}</label>
          <div className="mt-2 flex gap-1.5">
            {DIFFICULTIES.map((d) => (
              <button
                key={d}
                onClick={() => changeDifficulty(d)}
                className={
                  "flex-1 px-2 py-2 rounded-lg text-xs font-semibold border capitalize transition-colors " +
                  (difficulty === d
                    ? "bg-emerald-400 text-slate-900 border-emerald-400"
                    : "bg-white/5 text-slate-300 border-white/10 hover:bg-white/10")
                }
              >
                {d}
                <span className="block text-[10px] font-normal opacity-80">
                  {getTarget(cat, d, slotCount).toLocaleString()} {cat.unit}
                </span>
              </button>
            ))}
          </div>
        </div>

        {/* LINEUP SIZE */}
        <div className="px-5 mt-4">
          <label className="text-xs font-semibold text-slate-400 uppercase tracking-wide">Lineup size</label>
          <div className="mt-2 flex gap-1.5">
            {[10, 20].map((n) => (
              <button
                key={n}
                onClick={() => changeSlotCount(n)}
                className={
                  "flex-1 px-2 py-2 rounded-lg text-xs font-semibold border transition-colors " +
                  (slotCount === n
                    ? "bg-sky-400 text-slate-900 border-sky-400"
                    : "bg-white/5 text-slate-300 border-white/10 hover:bg-white/10")
                }
              >
                {n} spots
              </button>
            ))}
          </div>
        </div>

        {/* HARD MODE */}
        <div className="px-5 mt-4">
          <button
            onClick={() => setHardMode((h) => !h)}
            className="w-full flex items-center justify-between rounded-lg border border-white/10 bg-white/5 px-3 py-2.5"
          >
            <span className="text-left">
              <span className="block text-xs font-semibold text-slate-200">Hard Mode</span>
              <span className="block text-[10px] text-slate-500">No team hints — you're on your own</span>
            </span>
            <span
              className={
                "relative shrink-0 w-10 h-5.5 rounded-full transition-colors " +
                (hardMode ? "bg-rose-500" : "bg-white/15")
              }
              style={{ height: "22px" }}
            >
              <span
                className="absolute top-0.5 w-4.5 h-4.5 rounded-full bg-white transition-transform"
                style={{
                  width: "18px",
                  height: "18px",
                  left: "2px",
                  transform: hardMode ? "translateX(18px)" : "translateX(0)",
                }}
              />
            </span>
          </button>
        </div>

        {/* SPEED RUN */}
        <div className="px-5 mt-2">
          <button
            onClick={toggleSpeedRun}
            className="w-full flex items-center justify-between rounded-lg border border-white/10 bg-white/5 px-3 py-2.5"
          >
            <span className="text-left">
              <span className="block text-xs font-semibold text-slate-200">Speed Run</span>
              <span className="block text-[10px] text-slate-500">Race the clock through the whole lineup</span>
            </span>
            <span
              className={
                "relative shrink-0 w-10 h-5.5 rounded-full transition-colors " +
                (speedRun ? "bg-emerald-400" : "bg-white/15")
              }
              style={{ height: "22px" }}
            >
              <span
                className="absolute top-0.5 w-4.5 h-4.5 rounded-full bg-white transition-transform"
                style={{
                  width: "18px",
                  height: "18px",
                  left: "2px",
                  transform: speedRun ? "translateX(18px)" : "translateX(0)",
                }}
              />
            </span>
          </button>

          {speedRun && (
            <div className="mt-2 flex items-center justify-center gap-4 rounded-lg border border-white/10 bg-black/20 py-2">
              <div className="text-center">
                <p className="text-[10px] text-slate-500 uppercase tracking-wide">Time</p>
                <p className="font-scoreboard text-2xl text-white leading-none">
                  {runStartTime ? formatMs((runEndTime || Date.now()) - runStartTime) : "0:00.0"}
                </p>
              </div>
              {bestTime !== null && (
                <div className="text-center">
                  <p className="text-[10px] text-slate-500 uppercase tracking-wide">Best</p>
                  <p className="font-scoreboard text-2xl text-emerald-400 leading-none">{formatMs(bestTime)}</p>
                </div>
              )}
            </div>
          )}
        </div>

        {/* SPIN STATUS */}
        <div ref={summaryRef} className="px-5 mt-5">
          <p className="text-center text-xs text-slate-400">
            {roundComplete
              ? "Lineup complete"
              : `Tap the glowing badge on slot #${activeIndex + 1} of ${slotCount} to spin`}
          </p>
        </div>

        {/* PROGRESS */}
        <div className="px-5 mt-5">
          <div className="flex items-end justify-between mb-1">
            <p className="text-xs text-slate-400 uppercase tracking-wide">Lineup total</p>
            <p className="text-xs text-slate-400">{lockedCount}/{slotCount} slots locked</p>
          </div>
          <p className="font-scoreboard text-3xl text-white leading-none">
            {runningTotal.toLocaleString()}
            <span className="text-slate-500 text-xl"> / {target.toLocaleString()} {cat.unit}</span>
          </p>
          <div className="mt-2 h-2.5 rounded-full bg-white/10 overflow-hidden">
            <div
              className={"h-full rounded-full transition-all duration-500 " + (goalReached ? "bg-emerald-400" : "bg-amber-400")}
              style={{ width: progressPct + "%" }}
            />
          </div>
          {goalReached && <p className="mt-1.5 text-xs font-semibold text-emerald-400">Goal reached — lineup complete!</p>}

          <div className="mt-3 flex flex-wrap gap-2">
            {hardMode ? (
              <span className="px-3 py-1.5 rounded-full text-xs font-medium bg-white/5 text-slate-600 border border-white/10">
                Quick-lookup pool hidden in Hard Mode
              </span>
            ) : (
              <button
                onClick={() => setRevealed((r) => !r)}
                className="px-3 py-1.5 rounded-full text-xs font-medium bg-white/5 text-slate-300 border border-white/10 hover:bg-white/10"
              >
                {revealed ? "Hide quick-lookup pool" : "Show quick-lookup pool"}
              </button>
            )}
            <button
              onClick={resetBoard}
              className="px-3 py-1.5 rounded-full text-xs font-medium bg-white/5 text-slate-300 border border-white/10 hover:bg-white/10"
            >
              Reset
            </button>
            <button
              onClick={() => {
                setChallengeStatus("");
                setChallengePanel((p) => (p ? null : "menu"));
              }}
              className="px-3 py-1.5 rounded-full text-xs font-medium bg-amber-400/10 text-amber-400 border border-amber-400/30 hover:bg-amber-400/20"
            >
              🎯 Challenge
            </button>
          </div>

          {challengePanel && (
            <div className="mt-2 rounded-lg border border-white/10 bg-black/20 p-3 space-y-3">
              {challengePanel === "menu" && (
                <div className="flex gap-2">
                  <button
                    onClick={() => {
                      setChallengePanel("create");
                      setChallengeStatus("");
                    }}
                    className="flex-1 px-3 py-2 rounded-lg text-xs font-semibold bg-white/5 text-slate-200 border border-white/10 hover:bg-white/10"
                  >
                    Send a challenge
                  </button>
                  <button
                    onClick={() => {
                      setChallengePanel("enter");
                      setChallengeStatus("");
                    }}
                    className="flex-1 px-3 py-2 rounded-lg text-xs font-semibold bg-white/5 text-slate-200 border border-white/10 hover:bg-white/10"
                  >
                    Enter a code
                  </button>
                </div>
              )}

              {challengePanel === "create" &&
                (roundComplete ? (
                  <div>
                    <p className="text-xs text-slate-400">
                      Send this to a friend — they open this same app and enter the code to try to beat you.
                    </p>
                    {myChallengeCode ? (
                      <>
                        <p className="mt-2 text-center font-scoreboard text-3xl tracking-widest text-amber-400">
                          {myChallengeCode}
                        </p>
                        <button
                          onClick={copyChallengeMessage}
                          className="mt-2 w-full px-3 py-2 rounded-lg text-xs font-semibold bg-amber-400 text-slate-900 hover:bg-amber-300"
                        >
                          Copy challenge message
                        </button>
                      </>
                    ) : (
                      <button
                        onClick={createChallenge}
                        disabled={challengeBusy}
                        className="mt-2 w-full px-3 py-2 rounded-lg text-xs font-semibold bg-amber-400 text-slate-900 hover:bg-amber-300 disabled:opacity-50"
                      >
                        {challengeBusy ? "Creating…" : "Generate challenge code"}
                      </button>
                    )}
                  </div>
                ) : (
                  <p className="text-xs text-slate-400">
                    Finish this lineup first — a challenge is built from a completed run.
                  </p>
                ))}

              {challengePanel === "enter" && (
                <div>
                  <p className="text-xs text-slate-400">Enter the 5-letter code your friend sent you.</p>
                  <div className="mt-2 flex gap-2">
                    <input
                      type="text"
                      value={challengeInput}
                      onChange={(e) => setChallengeInput(e.target.value.toUpperCase())}
                      placeholder="ABCDE"
                      maxLength={5}
                      className="flex-1 min-w-0 bg-white/5 border border-white/10 rounded-lg px-3 py-2 text-sm text-white text-center tracking-widest placeholder-slate-500 outline-none focus:border-amber-400"
                    />
                    <button
                      onClick={loadChallenge}
                      disabled={challengeBusy || !challengeInput.trim()}
                      className="px-4 py-2 rounded-lg text-xs font-semibold bg-amber-400 text-slate-900 hover:bg-amber-300 disabled:opacity-50"
                    >
                      Go
                    </button>
                  </div>
                </div>
              )}

              {challengeStatus && <p className="text-xs text-emerald-400">{challengeStatus}</p>}
            </div>
          )}
        </div>

        {!hardMode && revealed && (
          <div className="mx-5 mt-3 rounded-xl border border-white/10 bg-black/20 p-3 max-h-56 overflow-y-auto">
            <p className="text-xs font-semibold text-amber-400 uppercase tracking-wide mb-2">{category} — quick-lookup pool</p>
            <p className="text-[11px] text-slate-500 mb-2">Anyone who played for the team works — these just auto-fill instantly.</p>
            {Object.keys(playersByTeam).sort().map((abbr) => (
              <div key={abbr} className="mb-2">
                <p className="text-[11px] font-semibold text-slate-300">{teamByAbbr(abbr, teams).name} ({abbr})</p>
                <p className="text-xs text-slate-500">
                  {playersByTeam[abbr].map((p) => `${p.name} (${p.value.toLocaleString()})`).join(", ")}
                </p>
              </div>
            ))}
          </div>
        )}

        {/* SLOTS */}
        <div className="px-5 py-5 space-y-2">
          <p className="text-xs font-semibold text-slate-400 uppercase tracking-wide mb-1">Your lineup — {category}</p>
          {slots.map((slot, i) => {
            const r = slot.result;
            let ring = "border-white/10";
            let badge = "bg-white/10 text-slate-300";
            let feedback = null;

            if (r) {
              if (r.status === "found") {
                ring = "border-emerald-400/60";
                badge = "bg-emerald-400 text-slate-900";
                feedback = <span className="text-emerald-400">{r.actual.toLocaleString()} {cat.unit} — added to your total</span>;
              } else if (r.status === "confirmed") {
                ring = "border-sky-400/60";
                badge = "bg-sky-400 text-slate-900";
                feedback = <span className="text-sky-400">Self-reported {r.actual.toLocaleString()} {cat.unit} — added to your total</span>;
              } else if (r.status === "wrongteam") {
                ring = "border-rose-500/50";
                badge = "bg-rose-500 text-white";
                feedback = hardMode ? (
                  <span className="text-rose-400">Not this team</span>
                ) : (
                  <span className="text-rose-400">Played for: {teamNames(r.actualTeams, teams)} — not this team</span>
                );
              } else if (r.status === "duplicate") {
                ring = "border-rose-500/50";
                badge = "bg-rose-500 text-white";
                feedback = <span className="text-rose-400">Already used in another slot</span>;
              } else if (r.status === "unverified") {
                ring = "border-amber-400/40";
                badge = "bg-amber-400/80 text-slate-900";
              } else if (r.status === "missed") {
                ring = "border-rose-500/60";
                badge = "bg-rose-500 text-white";
                feedback = <span className="text-rose-400">Missed — 0 {cat.unit}, moved on</span>;
              }
            }

            const team = slot.team ? teamByAbbr(slot.team, teams) : null;
            const isActive = i === activeIndex;
            const isUpcoming = i > activeIndex;
            const locked = r && isResolved(r.status);

            return (
              <div
                key={i}
                ref={(el) => (slotRefs.current[i] = el)}
                className={
                  "rounded-xl border bg-white/5 p-2.5 transition-opacity " +
                  ring +
                  (isUpcoming ? " opacity-40" : "") +
                  (isActive ? " ring-1 ring-amber-400/40" : "")
                }
              >
                <div className="flex items-center gap-2">
                  <div className={"w-7 h-7 rounded-full flex items-center justify-center text-xs font-bold shrink-0 " + badge}>
                    {r && r.status === "missed" ? "✕" : i + 1}
                  </div>

                  <button
                    onClick={() => spin()}
                    disabled={!isActive || !canSpin}
                    title={isActive && !locked ? "Tap to spin" : "Reshuffle this slot's team"}
                    className={
                      "shrink-0 w-12 h-7 rounded-md flex items-center justify-center text-[11px] font-bold text-white disabled:opacity-60 " +
                      (isActive && !locked && !spinning ? "glow-ring" : "")
                    }
                    style={{
                      background: isActive && spinning ? displayTeam.color : team ? team.color : "rgba(255,255,255,0.08)",
                      transition: "background 0.05s linear",
                    }}
                  >
                    {isActive && spinning ? displayTeam.abbr : team ? team.abbr : isActive ? "SPIN" : "—"}
                  </button>

                  <div className="relative flex-1 min-w-0">
                    <input
                      type="text"
                      placeholder={isUpcoming ? "Up next" : team ? "Player name" : "Spin first"}
                      value={slot.name}
                      disabled={!team || !isActive}
                      onChange={(e) => {
                        updateSlot(i, e.target.value);
                        setShowSuggestions(true);
                      }}
                      onFocus={() => setShowSuggestions(true)}
                      onBlur={() =>
                        setTimeout(() => {
                          setShowSuggestions(false);
                          markUnverifiedIfNeeded(i);
                        }, 150)
                      }
                      onKeyDown={(e) => {
                        if (e.key === "Enter") {
                          setShowSuggestions(false);
                          markUnverifiedIfNeeded(i);
                        }
                      }}
                      className="w-full bg-transparent text-sm text-white placeholder-slate-500 outline-none border-b border-white/10 focus:border-amber-400 py-1 disabled:opacity-40"
                    />
                    {isActive &&
                      !locked &&
                      showSuggestions &&
                      slot.name.trim().length > 0 &&
                      (() => {
                        const query = normalize(slot.name);
                        const suggestions = cat.players
                          .filter((p) => normalize(p.name).includes(query))
                          .slice(0, 8);
                        if (suggestions.length === 0) return null;
                        return (
                          <div className="absolute left-0 right-0 z-10 mt-1 max-h-48 overflow-y-auto rounded-lg border border-white/10 bg-slate-900 shadow-xl">
                            {suggestions.map((p) => (
                              <button
                                key={p.name}
                                onMouseDown={(e) => {
                                  e.preventDefault();
                                  selectPlayer(i, p);
                                }}
                                className="w-full flex items-center justify-between gap-2 px-3 py-1.5 text-left text-sm text-white hover:bg-white/10"
                              >
                                <span>{p.name}</span>
                                {!hardMode && (
                                  <span className="text-[10px] text-slate-500 shrink-0">{p.teams.join(", ")}</span>
                                )}
                              </button>
                            ))}
                          </div>
                        );
                      })()}
                  </div>
                  {r && r.status === "found" && (
                    <span className="shrink-0 text-sm font-semibold text-emerald-400">
                      {r.actual.toLocaleString()} {cat.unit}
                    </span>
                  )}
                  {r && r.status === "confirmed" && (
                    <span className="shrink-0 text-sm font-semibold text-sky-400">
                      {r.actual.toLocaleString()} {cat.unit}
                    </span>
                  )}
                  {r && r.status === "missed" && (
                    <span className="shrink-0 text-sm font-semibold text-rose-400">0 {cat.unit}</span>
                  )}
                </div>
                {feedback && <p className="mt-1.5 ml-9 text-xs">{feedback}</p>}

                {isActive && team && !locked && (
                  <div className="mt-1.5 ml-9 flex justify-end">
                    <button
                      onClick={() => missSlot(i)}
                      className="text-[11px] text-slate-500 hover:text-rose-400 underline decoration-dotted underline-offset-2"
                    >
                      Can't think of one? Skip (0 {cat.unit})
                    </button>
                  </div>
                )}

                {isActive && r && r.status === "unverified" && (
                  <div className="mt-2 ml-9 flex items-center gap-2">
                    <p className="text-xs text-amber-400 shrink-0">Not in our pool — self-report their {cat.unit}:</p>
                    <input
                      type="number"
                      placeholder={cat.unit}
                      value={slot.manualStat}
                      onChange={(e) => updateManualStat(i, e.target.value)}
                      onKeyDown={(e) => e.key === "Enter" && confirmManual(i)}
                      className="w-16 bg-transparent text-sm text-white placeholder-slate-500 outline-none border-b border-amber-400/50 py-0.5"
                    />
                    <button
                      onClick={() => confirmManual(i)}
                      className="shrink-0 px-2 py-1 rounded-md bg-amber-400 text-slate-900 text-xs font-semibold hover:bg-amber-300"
                    >
                      Add
                    </button>
                  </div>
                )}

                {isActive && locked && (
                  <p className="mt-1 ml-9 text-[11px] text-slate-500">Next slot up in a moment…</p>
                )}
              </div>
            );
          })}
        </div>

        {roundComplete && (
          <div className="mx-5 mb-5 rounded-xl border border-emerald-400/30 bg-emerald-400/10 p-3 text-center">
            <p className="text-sm font-semibold text-emerald-400">
              Lineup complete — {goalReached ? "you hit the target!" : "reset to try beating it."}
            </p>
            {speedRun && runEndTime && runStartTime && (
              <p className="mt-1 text-xs text-emerald-300">
                Finished in {formatMs(runEndTime - runStartTime)}
                {bestTime === runEndTime - runStartTime ? " — new best!" : ""}
              </p>
            )}
            {challengeTarget &&
              (() => {
                const won =
                  challengeTarget.speedRun && challengeTarget.timeMs
                    ? speedRun && runStartTime && runEndTime && runEndTime - runStartTime < challengeTarget.timeMs
                    : runningTotal > challengeTarget.total;
                return (
                  <p className={"mt-1 text-xs font-semibold " + (won ? "text-emerald-300" : "text-rose-400")}>
                    {won
                      ? `You beat challenge ${challengeTarget.code}! 🏆`
                      : `Didn't beat challenge ${challengeTarget.code} this time — reset to retry.`}
                  </p>
                );
              })()}
          </div>
        )}

        <div className="px-5 pb-6 text-center">
          <p className="text-[11px] text-slate-500">
            Tap the glowing badge on the current slot to spin, then start typing a name and tap it from the dropdown to lock it in — typing alone won't confirm it.
            If they're in our quick-lookup pool their stat fills in instantly; if not, self-report it and it still counts.
          </p>
        </div>
      </div>
    </div>
  );
}
